var breedLibraryIndex=new Map(),breedLibraryLimit=24,breedLibraryReturnFocus=null,breedLibrarySelecting=false;
function initializeBreedLibrary(){
    for(const entry of BREED_LIBRARY.entries){if(entry.species==='待核對')continue;for(const name of [entry.name,...entry.aliases])breedLibraryIndex.set(breedPictureKey(entry.species,name),entry);}
}
function setJournalDefaultAvatar(node,breed,species){
    const entry=breedLibraryIndex.get(breedPictureKey(species,breed));
    if(!entry){setJournalOriginalAvatar(node,breed,species);return;}
    const img=document.createElement('img');img.src=BREED_LIBRARY.assets[entry.asset];img.alt=(breed||entry.name)+'圖庫品種示意（非病患本人）';node.replaceChildren(img);
}
function openBreedLibraryPicker(){
    if(CURRENT_PROFILE?.role!=='admin'||breedPictureBusy)return;
    breedLibraryReturnFocus=document.activeElement;breedLibraryLimit=24;document.getElementById('breedLibrarySearch').value='';document.getElementById('breedLibraryStatus').textContent='挑選後會先預覽，請核對目前選擇的種類與品種，再按儲存。';
    document.getElementById('breedLibraryModal').hidden=false;renderBreedLibraryPicker();document.getElementById('breedLibrarySearch').focus();
}
function closeBreedLibraryPicker(){if(breedLibrarySelecting)return;document.getElementById('breedLibraryModal').hidden=true;breedLibraryReturnFocus?.focus();}
function renderBreedLibraryPicker(){
    const q=document.getElementById('breedLibrarySearch').value.trim().toLowerCase(),container=document.getElementById('breedLibraryGrid');container.replaceChildren();
    const entries=BREED_LIBRARY.entries.filter(e=>[e.filename,...e.aliases].join(' ').toLowerCase().includes(q));
    document.getElementById('breedLibraryCount').textContent='找到 '+entries.length+' 個檔案；同圖不同檔名保留供核對。';
    for(const entry of entries.slice(0,breedLibraryLimit)){
        const button=document.createElement('button');button.type='button';button.className='breed-library-tile';button.disabled=breedLibrarySelecting;
        const img=document.createElement('img');img.loading='lazy';img.src=BREED_LIBRARY.assets[entry.asset];img.alt=entry.filename;
        const name=document.createElement('span');name.textContent=entry.aliases[0]||entry.name;const filename=document.createElement('small');filename.textContent=entry.filename+' · '+entry.species;
        button.append(img,name,filename);button.onclick=()=>selectBreedLibraryPicture(entry);container.append(button);
    }
    document.getElementById('breedLibraryMore').hidden=entries.length<=breedLibraryLimit;
}
function searchBreedLibrary(){breedLibraryLimit=24;renderBreedLibraryPicker();}
function moreBreedLibraryPictures(){breedLibraryLimit+=24;renderBreedLibraryPicker();}
async function selectBreedLibraryPicture(entry){
    if(CURRENT_PROFILE?.role!=='admin'||breedPictureBusy||breedLibrarySelecting)return;
    const selectedSpecies=document.getElementById('breedPictureSpecies').value,selectedBreed=document.getElementById('breedPictureBreed').value;
    if(entry.species!=='待核對'&&entry.species!==selectedSpecies){document.getElementById('breedLibraryStatus').textContent='這張已標示為「'+entry.species+'」，目前種類是「'+selectedSpecies+'」。請先核對，沒有套用圖片。';return;}
    if(!selectedBreed)return;
    if(!confirm('將「'+entry.filename+'」作為「'+selectedSpecies+'／'+selectedBreed+'」的品種圖片？請確認圖像正確。選取後仍需儲存。'))return;
    const tenant=CURRENT_TENANT_ID,token=++breedPicturePreviewToken;breedLibrarySelecting=true;renderBreedLibraryPicker();
    try{
        // Reuse upload validation and compression; no database write occurs when choosing.
        const data=BREED_LIBRARY.assets[entry.asset],raw=atob(data.split(',')[1]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
        const file=new File([bytes],entry.filename,{type:entry.mime});const src=await compressBreedPicture(file);
        if(token!==breedPicturePreviewToken||tenant!==CURRENT_TENANT_ID||selectedSpecies!==document.getElementById('breedPictureSpecies').value||selectedBreed!==document.getElementById('breedPictureBreed').value)return;
        breedPictureDraft=src;document.getElementById('breedPictureFile').value='';
        const img=document.createElement('img');img.src=src;img.alt='從图庫選取的待儲存圖片';document.getElementById('breedPicturePreview').replaceChildren(img);
        document.getElementById('breedPictureDraftNote').textContent='已從圖庫挑選「'+entry.filename+'」，尚未儲存。';breedPictureMessage('圖片已選好，請核對後按「儲存品種圖片」。');document.getElementById('breedLibraryModal').hidden=true;document.getElementById('breedPictureSave').focus();
    }catch(error){document.getElementById('breedLibraryStatus').textContent='圖片選取失敗：'+error.message;}finally{breedLibrarySelecting=false;if(!document.getElementById('breedLibraryModal').hidden)renderBreedLibraryPicker();}
}
document.getElementById('breedLibraryModal').addEventListener('click',e=>{if(e.target.id==='breedLibraryModal')closeBreedLibraryPicker();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('breedLibraryModal').hidden)closeBreedLibraryPicker();});
initializeBreedLibrary();refreshManagedBreedAvatars();
